// Read-only production-harness replay with instrumentation supplied by Go overlay.
package main
import("compress/gzip";"encoding/json";"fmt";"os";"reflect";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/nanz";"github.com/minz/minzc/pkg/pipeline")
func load(path string,v any){f,e:=os.Open(path);if e!=nil {panic(e)};defer f.Close();z,e:=gzip.NewReader(f);if e!=nil {panic(e)};defer z.Close();if e=json.NewDecoder(z).Decode(v);e!=nil {panic(e)}}
func main(){root:=os.Getenv("MINZ_PC_BASELINE_DIR");if root=="" {panic("MINZ_PC_BASELINE_DIR required")};root+="/";source,e:=os.ReadFile(root+"source.nanz");if e!=nil {panic(e)};factory:=func() *hir.Module {m,e:=nanz.Parse(string(source),"../../../examples/nanz/grace_tokenizer_checked.nanz");if e!=nil {panic(e)};return m};var workload hir.ProfileWorkload;load(root+"workload.json.gz",&workload);m:=factory();oracle,e:=hir.RunLoopProfile(m,workload);if e!=nil {panic(e)};candidate:=factory();if e=hir.ApplyRegionComparePrototype(candidate,"region_eq");e!=nil{panic(e)};candidate.GraceRulePolicy=map[string]bool{};candidate.ForwardCopyPolicy=map[string]bool{};candidate.InvariantBasePolicy=map[string]bool{};candidate.PointerWalkPolicy=map[string]bool{};steps,e:=pipeline.CompileHIRSteps(candidate,pipeline.Options{AssertMode:"none",UseHIRGrace:true});if e!=nil {panic(e)};saved,e:=os.ReadFile(root+"baseline.a80");if e!=nil {panic(e)};if string(saved)!=steps.Assembly {panic("assembly differs from saved baseline")};run,e:=pipeline.RunZ80ProfileWorkload(steps,m,workload,*oracle);if e!=nil {panic(e)};var expected pipeline.Z80ProfileWorkloadEvidence;load(root+"target.json.gz",&expected);// SourceCompatibility executable/toolchain identity can differ for this instrumented helper.
 if !reflect.DeepEqual(run.Invocations,expected.Invocations) || !reflect.DeepEqual(run.Globals,expected.Globals) || !reflect.DeepEqual(run.Resources,expected.Resources) || !reflect.DeepEqual(run.BootstrapSHA256,expected.BootstrapSHA256) || run.BinarySHA256!=expected.BinarySHA256 || run.ExecutedSteps!=expected.ExecutedSteps || run.BootstrapTStates!=expected.BootstrapTStates {panic("replay differs from saved executable/state/traffic/timing evidence")};if run.TotalTStates!=2435966 {panic("total differs")};fmt.Printf("Exact replay PASS %dT SHA%s\n",run.TotalTStates,run.BinarySHA256)}
